INSERT INTO content_items (content_id, title, description, image_url, keywords, order_index) VALUES
(3,'Má','Ngón trỏ và ngón cái nắm vào má phải, các ngón khác nắm lại, lòng bàn tay hướng vào trong.','/images/pages/page_0082.png','má,cơ thể',78),
(3,'Chân','Tay trái giống chữ V, lòng bàn tay úp, đầu ngón tay hướng xuống dưới, đặt trước ngực. Tay phải giống số 1, lòng bàn tay hướng sang trái, đặt chạm đầu ngón trỏ phải vào đầu ngón trỏ trái.','/images/pages/page_0082.png','chân,cơ thể',79),
(3,'Tay','Tay trái khép, hơi khum lại, lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt phía trên tay trái, di chuyển tay xuống dưới chạm vào mu bàn tay trái.','/images/pages/page_0082.png','tay,cơ thể',80),
(3,'Đi','Tay phải giống chữ V, lòng bàn tay úp, đầu ngón tay hướng xuống dưới, đặt trước ngực, đưa tay về phía trước đồng thời cử động 2 ngón tay lần lượt ra - vào.','/images/pages/page_0083.png','đi,hoạt động',81),
(3,'Đứng','Tay trái duỗi thẳng, khép kín, lòng bàn tay hướng lên trên, đầu các ngón tay hướng ra ngoài. Tay phải giống chữ V, lòng bàn tay hướng vào trong, đầu các ngón tay đặt lên lòng bàn tay trái.','/images/pages/page_0083.png','đứng,hoạt động',82),
(3,'Ngồi','Tay trái giống chữ U, lòng bàn tay úp, đầu ngón tay hướng sang bên phải, đặt trước ngực. Tay phải giống chữ V, lòng bàn tay úp, đầu ngón tay hướng xuống dưới, ôm lấy ngón trỏ và ngón giữa tay trái.','/images/pages/page_0083.png','ngồi,hoạt động',83),
(3,'Nằm','Hai tay khép, lòng bàn tay hướng về phía trước, đặt chồng vào nhau, áp vào sau gáy, đầu hơi ngả ra phía sau.','/images/pages/page_0083.png','nằm,hoạt động',84),
(3,'Bò','Hai tay xoè, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt song song trước ngực, di chuyển lần lượt từng tay tiến ra phía trước (lặp lại hai lần).','/images/pages/page_0084.png','bò,hoạt động',85),
(3,'Lấy','Tay trái khép, lòng bàn tay ngửa, đầu ngón tay hướng về phía trước, đặt trước ngực. Tay phải giống chữ V, lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt chạm vào lòng bàn tay trái, giữ nguyên cánh tay, lật cổ tay lên - xuống (lặp lại 2 lần).','/images/pages/page_0084.png','lấy,hoạt động',86),
(3,'Chạy','Hai tay nắm, lòng bàn tay hướng vào nhau, đặt song song trước bụng, di chuyển lần lượt hai tay ra - vào (lặp lại 2 lần).','/images/pages/page_0084.png','chạy,hoạt động',87),
(3,'Nhảy','Tay trái khép, lòng bàn tay ngửa, đầu ngón tay hướng về phía trước, đặt trước ngực. Tay phải giống chữ V, lòng bàn tay hướng vào trong, đầu ngón tay hướng xuống dưới, đặt chạm đầu ngón tay vào gần cổ tay trái, di chuyển theo đường vòng cung đến đầu các ngón tay trái.','/images/pages/page_0084.png','nhảy,hoạt động',88),
(3,'Ngủ','Tay phải khép, hơi khum lại, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt áp vào má phải, đầu hơi ngả sang phải.','/images/pages/page_0085.png','ngủ,hoạt động',89),
(3,'Đi vệ sinh','1. Tay phải giống chữ V, lòng bàn tay úp, đầu ngón tay hướng xuống dưới, gập hai ngón tay lần lượt ra - vào và đưa tay về phía trước. 2. Ngón trỏ và ngón cái tay phải cong hình chữ C, ba ngón còn lại xoè ra, lòng bàn tay hướng ra ngoài, đặt trước ngực.','/images/pages/page_0085.png','đi vệ sinh,hoạt động',90),
(3,'Ăn','Tay phải chụm, lòng bàn tay hướng vào trong, đặt trước cổ, di chuyển tay lên sát miệng.','/images/pages/page_0085.png','ăn,hoạt động',91),
(3,'Uống','Tay phải giống chữ C, lòng bàn tay hướng sang trái, đặt trước ngực, đưa tay lên sát miệng.','/images/pages/page_0085.png','uống,hoạt động',92),
(3,'Chải đầu','Tay phải nắm, lòng bàn tay hướng sang trái, đặt bên phải đầu, di chuyển xuống dưới (lặp lại 2 lần).','/images/pages/page_0086.png','chải đầu,vệ sinh',93),
(3,'Mặc quần áo','Hai tay nắm, lòng bàn tay hướng vào trong, đặt ở hai bên vai, di chuyển đồng thời hai tay vào trong - xuống dưới.','/images/pages/page_0086.png','mặc quần áo,hoạt động',94),
(3,'Tắm','Hai tay mở xoè, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang hai bên, đặt áp vào người, tay trái đặt trên, tay phải đặt dưới, di chuyển đồng thời cả hai tay sang hai bên ngược chiều nhau (lặp lại 2 - 3 lần).','/images/pages/page_0086.png','tắm,vệ sinh',95),
(3,'Gội đầu','Hai tay mở, khum lại, lòng bàn tay hướng vào nhau, đặt chạm các đầu ngón tay vào hai bên đầu, di chuyển các ngón tay giống động tác gội đầu.','/images/pages/page_0086.png','gội đầu,vệ sinh',96),
(3,'Rửa tay','Hai tay khép, lòng bàn tay hướng vào nhau, đặt áp vào nhau, di chuyển hai tay ngược chiều nhau (lặp lại 2 - 3 lần).','/images/pages/page_0086.png','rửa tay,vệ sinh',97),
(3,'Rửa chân','Tay trái giống chữ V, lòng bàn tay úp, đầu ngón tay hướng xuống dưới, đặt trước ngực. Tay phải khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt chạm vào đầu ngón trỏ tay trái, di chuyển tiến lên, lùi xuống (2 lần).','/images/pages/page_0086.png','rửa chân,vệ sinh',98),
(3,'Rửa mặt','Hai tay khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt sát vào nhau, trước mặt, di chuyển đồng thời hai tay một vòng tròn quanh mặt theo chiều kim đồng hồ.','/images/pages/page_0087.png','rửa mặt,vệ sinh',99),
(3,'Đánh răng','Tay phải giống số 1, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt gần trước miệng, di chuyển tay qua lại (2 lần).','/images/pages/page_0087.png','đánh răng,vệ sinh',100),
(3,'Khóc','Tay phải giống chữ B, lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt gần phía trước mắt, di chuyển tay qua lại (2 lần).','/images/pages/page_0087.png','khóc,cảm xúc',101),
(3,'Cười','Tay phải giống chữ C, lòng bàn tay hướng sang trái, đặt gần khoé miệng phải, di chuyển tay qua lại (2 lần).','/images/pages/page_0087.png','cười,cảm xúc',102),
(3,'Bẩn','Tay phải khép, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt trước cổ bên phải, giữ nguyên cánh tay, gập mạnh cổ tay xuống dưới đồng thời mặt nhăn lại.','/images/pages/page_0087.png','bẩn,trạng thái',103),
(3,'Sạch','Tay phải khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt áp vào cánh tay trái, di chuyển mạnh tay xuống dưới và vẫy tay ra ngoài.','/images/pages/page_0087.png','sạch,trạng thái',104),
(3,'Quần','Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào quần và kéo nhẹ lên.','/images/pages/page_0088.png','quần,trang phục',105),
(3,'Giày thể thao','1. Tay trái khép, khum lại, lòng bàn tay ngửa, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đưa các đầu ngón tay phải vào trong lòng bàn tay trái. 2. Hai tay làm giống động tác buộc dây giày. 3. Hai tay nắm, đặt ở hai bên trên vai, đưa tay lên - tay xuống ngược chiều nhau.','/images/pages/page_0088.png','giày thể thao,giày dép',106),
(3,'Áo sơ mi','Tay phải nắm, ngón cái và ngón trỏ mở, khum lại, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt ở vị trí cổ áo, di chuyển tay xuống dưới đồng thời chạm hai đầu ngón tay lại.','/images/pages/page_0088.png','áo sơ mi,trang phục',107),
(3,'Áo phông','1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo và kéo nhẹ lên. 2. Tay phải giống chữ P, lòng bàn tay hướng xuống dưới, đặt trước ngực.','/images/pages/page_0089.png','áo phông,trang phục',108),
(3,'Áo len','1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo và kéo nhẹ lên. 2. Hai tay giống số 1, lòng bàn tay hướng vào nhau, đầu ngón tay hướng về phía trước, ngón trỏ phải đặt chéo, chạm trên ngón trỏ trái, trước ngực, xoay đồng thời hai cổ tay lên xuống giống hành động đan len.','/images/pages/page_0089.png','áo len,trang phục',109),
(3,'Áo veston','Hai tay giống chữ C, lòng bàn tay hướng vào trong, đặt chạm vào giữa ngực, tay phải đặt trên tay trái, giữ nguyên tay trái, di chuyển tay phải lên trên gần cổ.','/images/pages/page_0089.png','áo veston,trang phục',110),
(3,'Màu da cam','1+2. Tay phải giống chữ D, lòng bàn tay hướng sang trái, đặt trước ngực phải, sau đó thay đổi hình dạng tay giống chữ C, đặt trước ngực phải.','/images/pages/page_0100.png','màu da cam,cam,màu sắc',111),
(3,'Giống nhau','Hai tay giống số 1, lòng bàn tay úp, đầu ngón tay hướng về trước, đặt song song trước ngực, di chuyển đồng thời cả hai tay vào giữa và chạm vào nhau.','/images/pages/page_0100.png','giống nhau,so sánh',112),
(3,'Khác nhau','Hai tay giống số 1, lòng bàn tay hướng về trước, đầu ngón tay hướng lên trên, đặt song song trước ngực, di chuyển đồng thời cả hai tay sang hai bên.','/images/pages/page_0100.png','khác nhau,so sánh',113);
